package com.fasterxml.jackson.databind.ser;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonGenerator;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.JsonMappingException;
import com.fasterxml.jackson.databind.SerializerProvider;
import com.fasterxml.jackson.databind.introspect.AnnotatedMember;
import com.fasterxml.jackson.databind.ser.std.MapSerializer;
import java.io.*;
import java.math.*;
import java.util.*;
import java.util.HashMap;
import java.util.Map;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mock;
import org.mockito.MockitoAnnotations;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.*;

public class AnyGetterWriter_getAndSerialize_TriageGen1Test {

    private AnyGetterWriter _writer;

    @Mock
    private Accessor _accessor;

    @Mock
    private JsonGenerator _gen;

    @Mock
    private SerializerProvider _provider;

    @Mock
    private MapSerializer _mapSerializer;

    @Before
    public void setUp() throws Exception {
        MockitoAnnotations.openMocks(this);
        // Since AnyGetterWriter doesn't have a public constructor providing access to internal fields,
        // we assume for the purpose of this unit test that we are testing the logic provided.
        // In a real Jackson environment, these would be injected via constructor or reflection.
        _writer = mock(AnyGetterWriter.class, withSettings().useConstructor().defaultAnswer(CALLS_REAL_METHODS));

        // We use reflection to set private fields because the provided code relies on them
        setField(_writer, "_accessor", _accessor);
        setField(_writer, "_mapSerializer", _mapSerializer);
    }

    private void setField(Object target, String fieldName, Object value) throws Exception {
        java.lang.reflect.Field field = target.getClass().getDeclaredField(fieldName);
        field.setAccessible(true);
        field.set(target, value);
    }

    @Test
    public void testGetAndSerialize_ValueIsNull_ReturnsEarly() throws Exception {
        Object bean = new Object();
        when(_accessor.getValue(bean)).thenReturn(null);

        _writer.getAndSerialize(bean, _gen, _provider);

        verify(_accessor).getValue(bean);
        verifyNoInteractions(_mapSerializer);
        verifyNoInteractions(_gen);
    }

    @Test(expected = JsonMappingException.class)
    public void testGetAndSerialize_ValueIsNotMap_ThrowsException() throws Exception {
        Object bean = new Object();
        String notAMap = "not a map";
        when(_accessor.getValue(bean)).thenReturn(notAMap);
        when(_accessor.getName()).thenReturn("testGetter");

        try {
            _writer.getAndSerialize(bean, _gen, _provider);
        } catch (JsonMappingException e) {
            assert(e.getMessage().contains("not java.util.Map"));
            throw e;
        }
    }

    @Test
    public void testGetAndSerialize_MapWithSerializer_CallsSerializeFields() throws Exception {
        Object bean = new Object();
        Map<String, Object> map = new HashMap<>();
        map.put("key", "value");

        when(_accessor.getValue(bean)).thenReturn(map);
        // Ensure _mapSerializer is not null (already set in setUp)

        _writer.getAndSerialize(bean, _gen, _provider);

        verify(_mapSerializer).serializeFields(map, _gen, _provider);
    }

    @Test
    public void testGetAndSerialize_MapWithNullSerializer_DoesNothing() throws Exception {
        // This tests the branch where value is a Map but _mapSerializer is null
        setField(_writer, "_mapSerializer", null);

        Object bean = new Object();
        Map<String, Object> map = new HashMap<>();
        when(_accessor.getValue(bean)).thenReturn(map);

        _writer.getAndSerialize(bean, _gen, _provider);

        // If _mapSerializer is null, the method reaches the end of the block without doing anything
        verifyNoInteractions(_gen);
    }
}

/**
 * Dummy Accessor class to allow the test to compile if the real one isn't accessible.
 * In a real scenario, this would be the actual com.fasterxml.jackson.databind.ser.impl.AnyGetterWriter.Accessor
 */
interface Accessor {
    Object getValue(Object bean) throws Exception;
    String getName();
}
